    "id": "v5_p42_1",
    "volume": 5,
    "vol_file": "vol05.html",
    "vol_short_label": "第二部 第一章 黒騎士の挑戦",
    "para_index": 42,
    "type": "本文",
    "era_year": "伝説時代",
    "places": "",
    "translation_tagged": "されば{{person:アーサー|アーサー}}{{office:王|王}}の御胸は大いなる歓喜に大きく膨らみ、かの武門にふさわしい冒険を求めて森の中へと馬を進めながら、古雅にして趣深き歌を高らかに口ずさまれた。",
    "raw_tagged": "So {{office:王|King}} {{person:アーサー|Arthur}}'s heart expanded with great joy, and he chanted a quaint song as he rode through the forest upon the quest of that knightly adventure.",
    "zh_tw_tagged": "是以{{person:アーサー|亞瑟}}{{office:王|王}}心懷莫大歡愉而胸襟大開，一邊策馬穿行林間去追尋那場豪俠奇遇，一邊吟唱起一首古雅別致的歌謠。",
    "zh_cn_tagged": "是以{{person:アーサー|亚瑟}}{{office:王|王}}心怀莫大欢愉而胸襟大开，一边策马穿行林间去追寻那场豪侠奇遇，一边吟唱起一首古雅别致的歌谣。",
    "ko_tagged": "그리하여 {{person:アーサー|아서}} {{office:王|왕}}의 가슴은 크나큰 기쁨으로 한껏 부풀어 올랐고, 무인다운 그 모험을 찾아 숲속으로 말을 몰아 나아가면서 고풍스럽고도 멋스러운 노래 한 가락을 흥얼거렸다.",
    "vol_short_label_i18n": {
      "ja": "第二部 第一章 黒騎士の挑戦",
      "en": "Part II Ch. I: Quest of the Sable Knight",
      "zh_tw": "第二部 第一章 黑騎士的挑戰",
      "zh_cn": "第二部 第一章 黑骑士的挑战",
      "ko": "제2부 제1장 검은 기사의 도전"
    }
