    "era_year": "伝説時代",
    "places": "",
    "translation_tagged": "「そのようなことはいたさぬ」と{{person:黒騎士|黒騎士}}は言った。「なぜといって見よ、私はすでに貴公を打ち倒したのだ。さればその盾を私へ引き渡すがよい。かしこの林檎の木に吊り下げておくゆえ、貴公はこれまでに敗れた他の者どもがそうしたように、おのれの道を引き返して立ち去るがよい」",
    "raw_tagged": "\"That will I not do,\" said the {{person:黒騎士|Sable Knight}}, \"for, lo! I have overthrown thee. Wherefore deliver thou to me thy shield, that I may hang it upon yonder apple-tree, and go thy way as others have done before thee. \"",
    "zh_tw_tagged": "「我絕不那樣做，」{{person:黒騎士|黑騎士}}說道，「因為你看！我已將你擊落馬下了。故此，快把你的盾牌交給我，好讓我將它掛到那邊的蘋果樹上去，而你便如同先前敗在我手下的其他人一樣，自行離去吧。」",
    "zh_cn_tagged": "“我绝不那样做，”{{person:黒騎士|黑骑士}}说道，“因为你看！我已将你击落马下了。故此，快把你的盾牌交给我，好让我将它挂到那边的苹果树上去，而你便如同先前败在我手下的其他人一样，自行离去吧。”",
    "ko_tagged": "“나는 그리하지 않겠다.” {{person:黒騎士|흑기사}}가 말하였다. “보라! 내가 이미 그대를 쓰러뜨렸기 때문이다. 그러니 내가 저기 저 사과나무 위에 내걸 수 있도록 그대의 방패를 내게 넘겨주고, 그대보다 앞서 다녀간 다른 자들이 그러했듯이 순순히 갈 길을 가도록 하라.”",
    "vol_short_label_i18n": {
      "ja": "第二部 第二章 黒騎士との死闘",
      "en": "Part II Ch. II: Battle with the Sable Knight",
      "zh_tw": "第二部 第二章 與黑騎士的死鬥",
      "zh_cn": "第二部 第二章 与黑骑士的死斗",
      "ko": "제2부 제2장 검은 기사와의 사투"
    }
