    "era_year": "伝説時代",
    "places": "",
    "translation_tagged": "すると{{person:アーサー|アーサー}}{{office:王|王}}は言った。「それは余にも分からぬ。だが、それでも余はでき得るかぎり速やかに、今から何らかの武器を探し求めるつもりだ。たとえ樫の木の棍棒よりましな武器が手に入らぬとしても、そのような粗末な得物ひとつを携えてでも、余はふたたびこの戦いに挑むであろうからな」",
    "raw_tagged": "And {{office:王|King}} {{person:アーサー|Arthur}} said, \"That I know not, nevertheless I will presently seek for some weapon as soon as may be. For, even an I have no better weapon than an oaken cudgel, yet would I assay this battle again with so poor a tool as that.\"",
    "zh_tw_tagged": "{{person:アーサー|亞瑟}}{{office:王|王}}說道：「這我固然不知，然而我即刻便要設法儘快尋覓一件趁手兵刃。因為，縱使我找不到比一根橡木棍棒更好的武器，哪怕只憑那樣簡陋寒酸的器具，我也定要再度挑戰這場對決。」",
    "zh_cn_tagged": "{{person:アーサー|亚瑟}}{{office:王|王}}说道：“这我固然不知，然而我即刻便要设法尽快寻觅一件趁手兵刃。因为，纵使我找不到比一根橡木棍棒更好的武器，哪怕只凭那样简陋寒酸的器具，我也定要再度挑战这场对决。”",
    "ko_tagged": "그러자 {{person:アーサー|아서}} {{office:王|왕}}이 말하였다. “그거야 나도 알지 못하오. 그렇지만 나는 곧바로 가능한 한 빨리 어떤 무기든 찾아 나설 것이오. 설령 참나무 몽둥이보다 더 나은 무기를 구하지 못한다 할지라도, 그토록 보잘것없는 연장 하나만 들고서라도 나는 기어코 이 싸움에 다시 도전할 것이기 때문이오.”",
    "vol_short_label_i18n": {
      "ja": "第二部 第三章 宝剣エクスカリバー",
      "en": "Part II Ch. III: Winning of Excalibur",
      "zh_tw": "第二部 第三章 寶劍艾克斯卡利伯",
      "zh_cn": "第二部 第三章 宝剑艾克斯卡利伯",
      "ko": "제2부 제3장 보검 엑스칼리버"
    }
