    "era_year": "伝説時代",
    "places": "",
    "translation_tagged": "すると{{person:グィネヴィア|グィネヴィア}}姫が仰せられた。「して、なぜ帽子を脱ぐことができぬと申すのですか、これ、無愛想な若者よ？」",
    "raw_tagged": "Quoth the Lady {{person:グィネヴィア|Guinevere}}: \"And why canst thou not take off thy cap, thou surly fellow?\"",
    "zh_tw_tagged": "{{person:グィネヴィア|桂妮薇兒}}小姐開口問道：「你這倔強無禮的小子，為何不能摘下你的帽子？」",
    "zh_cn_tagged": "{{person:グィネヴィア|桂妮薇儿}}小姐开口问道：“你这倔强无礼的小子，为何不能摘下你的帽子？”",
    "ko_tagged": "그러자 {{person:グィネヴィア|기네비어}} 아가씨가 말하였다. “대체 어찌하여 모자를 벗을 수 없다는 것이냐, 이 무뚝뚝하고 버릇없는 녀석아?”",
    "vol_short_label_i18n": {
      "ja": "第三部 第一章 王の変装",
      "en": "Part III Ch. I: The King in Disguise",
      "zh_tw": "第三部 第一章 國王的喬裝",
      "zh_cn": "第三部 第一章 国王的乔装",
      "ko": "제3부 제1장 왕의 변장"
    }
